const paths={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',book:'M12 5v16M3 4q5-2 9 1 4-3 9-1v15q-5-2-9 2-4-4-9-2z',math:'M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2zM7 8h4M9 6v4M15 8h3M7 15l3 3M10 15l-3 3M15 15h3M15 18h3',leaf:'M20 3C8 1 1 9 6 17c8 7 16-2 14-14ZM4 21 15 9',family:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-3a7 7 0 0 1 14 0v3M18 6a3 3 0 0 1 0 6M19 15q4 1 3 6',sound:'M11 4 6 8H3v8h3l5 4zM15 8q4 4 0 8M18 4q8 8 0 16',mute:'M11 4 6 8H3v8h3l5 4zM16 9l6 6M22 9l-6 6',arrow:'M4 12h16M14 6l6 6-6 6',back:'M20 12H4M10 6l-6 6 6 6',check:'M4 12l5 5L20 6',download:'M12 3v12M6 9l6 6 6-6M3 16v5h18v-5',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',clock:'M12 8v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'M5 5l14 14M19 5 5 19',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6'};
export const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.leaf}"/></svg>`;
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const button=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
export const audioButton=text=>button(icon('sound')+' Escuchar','speak','secondary small',`data-text="${esc(text)}"`);
export const companion=text=>`<aside class="companion"><img class="avatar" src="./assets/forest.webp" alt="Lía, tu zorrita acompañante"><p><strong>LÍA TE ACOMPAÑA</strong>${text}</p></aside>`;
let toastTimer;export function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),6500);}
let audioTimer,audioGeneration=0;export function stopAudio(){audioGeneration++;clearTimeout(audioTimer);if('speechSynthesis'in window)window.speechSynthesis.cancel();document.querySelectorAll('.speaking').forEach(x=>x.classList.remove('speaking'));}
export function speak(text,settings,element,onEnd){stopAudio();const generation=audioGeneration;if(!settings.sound){toast('El sonido está silenciado. Puedes activarlo con el botón del altavoz.');return;}if(!('speechSynthesis'in window)){toast('Este navegador no ofrece voz. Lee el texto en pantalla o pide a un adulto que lo lea contigo.');return;}const voices=speechSynthesis.getVoices().filter(v=>v.lang.startsWith('es'));const voice=voices.find(v=>v.localService)||voices[0];if(!navigator.onLine&&(!voice||!voice.localService)){toast('No hay una voz española sin conexión. Puedes leer el texto o escucharlo con un adulto.');return;}const u=new SpeechSynthesisUtterance(text);u.lang='es-ES';u.rate=.85;if(voice)u.voice=voice;u.onstart=()=>{if(generation!==audioGeneration)return;clearTimeout(audioTimer);element?.classList.add('speaking');};u.onend=()=>{if(generation!==audioGeneration)return;clearTimeout(audioTimer);element?.classList.remove('speaking');onEnd?.();};u.onerror=e=>{clearTimeout(audioTimer);element?.classList.remove('speaking');if(e.error!=='interrupted'&&e.error!=='canceled')toast('No se ha podido reproducir la voz. El texto sigue aquí: puedes leerlo con un adulto.');};audioTimer=setTimeout(()=>{stopAudio();toast('La voz no está disponible ahora. Puedes continuar con el texto o con un adulto.');},7000);speechSynthesis.speak(u);}
export function showDialog(content){stopAudio();const d=document.querySelector('#modal');d.innerHTML=`<button class="icon-button close-dialog" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button>${content}`;const heading=d.querySelector('h2');if(heading){heading.id='modal-title';d.setAttribute('aria-labelledby','modal-title');}if(!d.open)d.showModal();}
